import assert from 'node:assert/strict';
import {resolve} from 'node:path';
export async function cenarios({p,d,fechar,check,layout,medir,abrir,rpc,tag,ids,mobile,out,perfil}){
 const sum=async(texto,opcional=false)=>{const s=d().locator('summary').filter({hasText:texto}).first();if(opcional&&!(await s.count()))return;await s.waitFor();if((await s.locator('..').getAttribute('open'))===null)await s.click()};
 const salvo=async(nome)=>{await d().getByRole('button',{name:nome,exact:true}).click();await p.locator('dialog[open]').waitFor({state:'hidden'})};
 const srv=tag+' serviço',emp=tag+' pessoa',forn=tag+' fornecedor',obj=tag+' equipamento',local=tag+' bancada';
 await abrir('Serviços','/catalogo',()=>p.getByRole('button',{name:'Novo serviço',exact:true}).waitFor());
 await medir('Serviços · cadastrar simples',async()=>{await p.getByRole('button',{name:'Novo serviço',exact:true}).click();await d().locator('[name=descricao]').fill(srv);await d().locator('[name=preco]').fill('150');await layout('Cadastro serviço');await salvo('Salvar cadastro')});
 await medir('Serviços · buscar',async()=>{await p.locator('.catalogo-real input[type=search], .catalogo-real .catalogo-busca input').first().fill(srv);await p.locator('.catalogo-card').filter({hasText:srv}).waitFor()});
 let row=()=>p.locator('.catalogo-card').filter({hasText:srv});
 await medir('Serviços · editar ficha e custos',async()=>{await row().getByRole('button',{name:'Editar',exact:true}).click();await sum('Detalhes do serviço');await d().getByLabel('Orientações e detalhes',{exact:true}).fill('Conferir funcionamento antes e depois do atendimento.');await d().getByLabel('Tempo previsto',{exact:true}).fill('75');await sum('Custos e margem');await d().getByLabel('Custo direto por unidade',{exact:true}).fill('30');await layout('Serviço completo');await salvo('Salvar cadastro')});
 await medir('Serviços · consultar ficha',async()=>{await row().locator('.catalogo-abrir-ficha').click();await d().getByText('Conferir funcionamento antes e depois do atendimento.',{exact:true}).waitFor();await layout('Ficha serviço')});await fechar();
 const ficha=await rpc('consultar_ficha_servico',{p_item:ids.servicos[0]});check('Serviço preço, custo e duração persistidos',ficha.preco_padrao_centavos===15000&&ficha.custo_centavos===3000&&ficha.ficha.duracao_minutos===75);
 await abrir('Funcionários','/funcionarios',()=>p.getByPlaceholder('Nome, função ou contato').waitFor());
 await medir('Funcionários · cadastrar simples',async()=>{await p.getByRole('button',{name:'Novo funcionário',exact:true}).click();await d().locator('[name=nome]').fill(emp);await salvo('Salvar funcionário')});
 await medir('Funcionários · buscar',async()=>{await p.getByPlaceholder('Nome, função ou contato').fill(emp);await p.getByRole('button',{name:'Abrir ficha de '+emp,exact:true}).waitFor()});
 await medir('Funcionários · editar ficha',async()=>{await p.getByRole('button',{name:'Abrir ficha de '+emp,exact:true}).click();await sum('Contato e função',true);await d().locator('[name=funcao]').fill('Técnico de teste');await d().locator('[name=email]').fill('qa@example.invalid');await d().locator('[name=observacoes]').fill('Cadastro fictício para validação.');await layout('Ficha funcionário');await salvo('Salvar funcionário')});
 await medir('Funcionários · reabrir ficha',async()=>{await p.getByRole('button',{name:'Abrir ficha de '+emp,exact:true}).click();assert.equal(await d().locator('[name=funcao]').inputValue(),'Técnico de teste');await layout('Funcionário reaberto')});await fechar();
 check('Funcionário único',(await rpc('listar_funcionarios')).filter(x=>x.nome===emp).length===1);
 await abrir('Fornecedores','/fornecedores',()=>p.getByRole('button',{name:'Novo fornecedor',exact:true}).waitFor());
 await medir('Fornecedores · cadastrar simples',async()=>{await p.getByRole('button',{name:'Novo fornecedor',exact:true}).click();await d().locator('[name=nome]').fill(forn);await salvo('Salvar fornecedor')});
 await medir('Fornecedores · buscar',async()=>{await p.getByLabel('Buscar fornecedores',{exact:true}).fill(forn);await p.locator('.fornecedor-card').filter({hasText:forn}).waitFor()});
 await medir('Fornecedores · editar contato',async()=>{await p.locator('.fornecedor-card').filter({hasText:forn}).getByRole('button',{name:'Editar',exact:true}).click();await sum('Mais informações',true);await d().locator('[name=email]').fill('compras@example.invalid');await d().locator('[name=endereco]').fill('Rua de teste, 123');await layout('Fornecedor');await salvo('Salvar fornecedor')});
 const fs=await rpc('listar_fornecedores',{p_busca:forn,p_arquivados:false,p_pagina:0});check('Fornecedor único e contato persistido',fs.itens.length===1&&fs.itens[0].email==='compras@example.invalid');
 await abrir('Localização','/localizacao',()=>p.getByRole('button',{name:'Guardar item',exact:true}).waitFor());
 await medir('Localização · cadastrar local durante guarda',async()=>{await p.getByRole('button',{name:'Guardar item',exact:true}).click();await d().locator('[name=descricao]').fill(obj);await d().getByRole('button',{name:'Novo local',exact:true}).click();await d().locator('[name=nome]').fill(local);await d().getByRole('button',{name:'Salvar local',exact:true}).click();await d().locator('[name=descricao]').waitFor();await d().getByRole('combobox',{name:'Onde vai ficar?',exact:true}).selectOption({label:local});await layout('Guardar item');await salvo('Guardar item')});
 await medir('Localização · buscar item',async()=>{await p.getByPlaceholder('Descrição, etiqueta ou número de série').fill(obj);await p.locator('.loc-linha').filter({hasText:obj}).waitFor()});
 await medir('Localização · mudar local',async()=>{await p.getByRole('button',{name:'Mudar local de '+obj,exact:true}).click();await d().getByRole('combobox',{name:'Onde vai ficar?',exact:true}).selectOption({label:local});await salvo('Salvar local')});
 await medir('Localização · imprimir etiqueta PDF',async()=>{await p.getByRole('button',{name:'Imprimir etiqueta de '+obj,exact:true}).click();const down=p.waitForEvent('download');await d().getByRole('button',{name:'Baixar PDF para imprimir',exact:true}).click();const f=await down,stream=await f.createReadStream();const bs=[];for await(const b of stream)bs.push(b);check('Etiqueta PDF válida',Buffer.concat(bs).subarray(0,4).toString()==='%PDF')});await fechar();
 const fis=await rpc('listar_itens_fisicos',{p_busca:obj,p_situacao:'',p_local:null,p_vinculo:{},p_antes:null,p_id_antes:null});check('Item guardado no local correto',fis.itens.length===1&&fis.itens[0].local_id===ids.locais[0]);
 await abrir('Compras','/compras',()=>p.getByRole('button',{name:'Registrar compra',exact:true}).waitFor());
 await medir('Compras · registrar compra a prazo',async()=>{await p.getByRole('button',{name:'Registrar compra',exact:true}).click();const combos=d().getByRole('combobox');await combos.filter({hasNot:p.locator('option')}).first().fill(forn);await d().getByRole('option').filter({hasText:forn}).click();await d().locator('[name=documento]').fill(tag);const input=d().locator('input[role=combobox]').last();await input.fill(tag+' peça');await d().getByRole('option').filter({hasText:tag+' peça'}).click();await d().getByLabel('Quantidade',{exact:true}).fill('3');await d().getByLabel('Custo unitário (R$)',{exact:true}).fill('11.11');await layout('Compra');await d().getByRole('button',{name:/^Confirmar compra e entrada/}).click();await p.getByRole('heading',{name:'Detalhes da compra',exact:true}).waitFor();await d().getByRole('button',{name:'Cancelar esta compra',exact:true}).waitFor()});
 const compra=await rpc('consultar_compra_estoque',{p_compra:ids.compras[0]});check('Compra total e conta a pagar exatos',compra.total_centavos===3333&&compra.titulos.reduce((s,t)=>s+t.aberto_centavos,0)===3333&&compra.titulos.every(t=>t.baixado_centavos===0));
 const est=await rpc('listar_estoque',{p_busca:tag+' peça',p_filtro:'',p_pagina:0});check('Estoque recebeu três unidades',est.itens.find(x=>x.id===ids.produto)?.saldo===3);
 await medir('Compras · cancelar e reverter',async()=>{await d().getByRole('button',{name:'Cancelar esta compra',exact:true}).click();await d().locator('[name=motivo]').fill('Encerramento do teste fictício');await d().getByRole('button',{name:'Confirmar cancelamento da compra',exact:true}).click();await d().getByText('Compra cancelada:',{exact:false}).waitFor();await layout('Compra cancelada')});
 if(['retifica','assistencia_celulares','manutencao_climatizacao','limpeza_geral'].includes(perfil))await p.screenshot({path:resolve(out,perfil+(mobile?'-celular':'-desktop')+'.png')});
}

